static void Geometry(Assembly old,Assembly current,StringBuilder log){using(var db=new Database(true,true)){var previous=HostApplicationServices.WorkingDatabase;HostApplicationServices.WorkingDatabase=db;try{using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForWrite);var block=new BlockTableRecord{Name="PERF_FRAME"};bt.Add(block);tr.AddNewlyCreatedDBObject(block,true);var p=new Polyline();p.AddVertexAt(0,new Point2d(0,0),0,0,0);p.AddVertexAt(1,new Point2d(420,0),0,0,0);p.AddVertexAt(2,new Point2d(420,297),0,0,0);p.AddVertexAt(3,new Point2d(0,297),0,0,0);p.Closed=true;block.AppendEntity(p);tr.AddNewlyCreatedDBObject(p,true);var text=new DBText{TextString="TITLE",Position=new Point3d(20,15,0),Height=3};block.AppendEntity(text);tr.AddNewlyCreatedDBObject(text,true);var model=(BlockTableRecord)tr.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForWrite);for(int i=0;i<8;i++){var br=new BlockReference(new Point3d(i*2000,0,0),block.ObjectId){Rotation=i*.2,ScaleFactors=new Scale3d(1+i*.1)};model.AppendEntity(br);tr.AddNewlyCreatedDBObject(br,true);}tr.Commit();}
