var after=Full(current,db,lib);for(int i=0;i<8;i++){var x=(string)before[i].GetType().GetProperty("Title").GetValue(before[i],null);var y=(string)after[i].GetType().GetProperty("Title").GetValue(after[i],null);if(x!=y||y!="TITLE")throw new System.Exception("full scan text changed or geometry flag leaked: "+x+" / "+y);}log.AppendLine("PASS geometry-only scan: same corners as full scan for 8 rotated/scaled frames; subsequent full scan still reads TITLE correctly");}finally{HostApplicationServices.WorkingDatabase=previous;}}}
